import{_ as e,a as r,b as a,c as i,d as o,e as l,f as d,g as n,h as s,i as c,j as h,k as p,l as g,m as f,n as u}from"./chunks/pc-port-v2.Dl-DjBnu.js";import{_ as m,o as b,c as y,a5 as x}from"./chunks/framework.CcrBcQWS.js";const L=JSON.parse('{"title":"External Port Information","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/interface/external-port.md","filePath":"manual/interface/external-port.md","lastUpdated":1787021357000}'),P={name:"manual/interface/external-port.md"};function v(C,t,w,_,N,V){return b(),y("div",null,[...t[0]||(t[0]=[x('<h1 id="external-port-information" tabindex="-1">External Port Information <a class="header-anchor" href="#external-port-information" aria-label="Permalink to &quot;External Port Information&quot;">​</a></h1><h2 id="overall-external-port-panel" tabindex="-1">Overall External Port Panel <a class="header-anchor" href="#overall-external-port-panel" aria-label="Permalink to &quot;Overall External Port Panel&quot;">​</a></h2><p>There are two panel layouts — <strong>version 1</strong> and <strong>version 2</strong> — and which one your robot has depends on the robot. The quickest way to tell them apart is the pair of USB-C ports on the right edge: version 1 labels them <strong>VISION / MOTION</strong>, version 2 labels them <strong>U-PC / R-PC</strong>. They are the same two ports — version 2 names the PC each one reaches instead of its role.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>The panel layout can differ between versions. Please <a href="/RBQ/nightly/manual/troubleshooting/error-reporting">contact us</a> if you are unsure which one your robot has.</p></div></div><div class="rbq-compare"><figure id="panel-v1"><img src="'+e+'" alt="External port panel, version 1"><figcaption>Version 1</figcaption></figure><figure id="panel-v2"><img src="'+r+'" alt="External port panel, version 2"><figcaption>Version 2</figcaption></figure></div><h3 id="ports-by-version" tabindex="-1">Ports by version <a class="header-anchor" href="#ports-by-version" aria-label="Permalink to &quot;Ports by version {#ports-by-version}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Port</th><th style="text-align:left;">Version 1</th><th style="text-align:left;">Version 2</th></tr></thead><tbody><tr><td style="text-align:left;">Power</td><td style="text-align:left;"><code>POWER</code></td><td style="text-align:left;"><code>POWER</code></td></tr><tr><td style="text-align:left;">Power · CAN</td><td style="text-align:left;"><code>PWR-CAN</code></td><td style="text-align:left;"><code>PWR/CAN</code></td></tr><tr><td style="text-align:left;">Power · LAN</td><td style="text-align:left;"><code>12V-LAN</code> ×3</td><td style="text-align:left;"><code>12V/LAN</code> ×3</td></tr><tr><td style="text-align:left;">LiDAR</td><td style="text-align:left;"><code>LiDAR</code></td><td style="text-align:left;">No dedicated port — use <code>12V/LAN</code></td></tr><tr><td style="text-align:left;">Emergency stop</td><td style="text-align:left;"><code>EMO</code></td><td style="text-align:left;"><code>EMO</code></td></tr><tr><td style="text-align:left;">USB-C (direct to PC)</td><td style="text-align:left;"><code>VISION</code>, <code>MOTION</code></td><td style="text-align:left;"><code>U-PC</code>, <code>R-PC</code></td></tr></tbody></table><h2 id="charging-power-switch" tabindex="-1">Charging &amp; Power Switch <a class="header-anchor" href="#charging-power-switch" aria-label="Permalink to &quot;Charging &amp; Power Switch&quot;">​</a></h2><p>Both versions carry the same three elements — the power port with its cover, the power button, and the robot status lights — but lay them out differently.</p><div class="rbq-compare"><figure><img src="'+a+'" alt="Charging and power switch, version 1"><figcaption>Version 1</figcaption></figure><figure><img src="'+i+'" alt="Charging and power switch, version 2"><figcaption>Version 2</figcaption></figure></div><table tabindex="0"><thead><tr><th style="text-align:left;">Element</th><th style="text-align:left;">Version 1</th><th style="text-align:left;">Version 2</th></tr></thead><tbody><tr><td style="text-align:left;">Power port cover</td><td style="text-align:left;">Hinged flip cover</td><td style="text-align:left;">Screw-down round cover</td></tr><tr><td style="text-align:left;">Robot status lights</td><td style="text-align:left;">Horizontal strip above the power port</td><td style="text-align:left;">Vertical strip beside the power button</td></tr><tr><td style="text-align:left;">Power button</td><td style="text-align:left;">Below the power port</td><td style="text-align:left;">Bottom left, next to the status lights</td></tr></tbody></table><p>- Robot Battery Lights</p><figure><img src="'+o+'" alt="Robot battery indicator lights" style="width:400px;"></figure><p>- Robot Status Lights (blinking)</p><figure><img src="'+l+'" alt="Robot status indicator lights" style="width:500px;"></figure><p>- Power Button Status</p><figure><img src="'+d+'" alt="Power button status" style="width:400px;"></figure><h2 id="user-port-pin-map" tabindex="-1">User Port Pin Map <a class="header-anchor" href="#user-port-pin-map" aria-label="Permalink to &quot;User Port Pin Map&quot;">​</a></h2><p>The user ports differ between versions — see <a href="#ports-by-version">Ports by version</a> for the full comparison. Pin maps for each port type follow below.</p><div class="rbq-compare"><figure><img src="'+n+'" alt="User ports, version 1"><figcaption>Version 1</figcaption></figure><figure><img src="'+s+'" alt="User ports, version 2"><figcaption>Version 2</figcaption></figure></div><h3 id="power" tabindex="-1">POWER <a class="header-anchor" href="#power" aria-label="Permalink to &quot;POWER&quot;">​</a></h3><div class="pin-map-row"><figure style="margin:0;"><img src="'+c+'" alt="User port POWER pin map"></figure><div><table><tr><th>Pin</th><th>Function</th><th>Color</th></tr><tr><td>1</td><td>VCC</td><td>Red</td></tr><tr><td>2</td><td>GND</td><td>Black</td></tr></table><ul><li>VCC: 42.0 ~ 58.4V (Battery Power)</li><li>Max. Current: 5A</li></ul></div></div><p><br><br></p><h3 id="pwr-can" tabindex="-1">PWR-CAN <a class="header-anchor" href="#pwr-can" aria-label="Permalink to &quot;PWR-CAN&quot;">​</a></h3><div class="pin-map-row"><figure style="margin:0;"><img src="'+h+'" alt="User port PWR-CAN pin map"></figure><div><table><tr><th>Pin</th><th>Function</th><th>Color</th></tr><tr><td>1</td><td>VCC</td><td>Red</td></tr><tr><td>2</td><td>GND</td><td>Black</td></tr><tr><td>3</td><td>CAN High</td><td>White</td></tr><tr><td>4</td><td>CAN Low</td><td>Blue</td></tr></table><ul><li>VCC: 42.0 ~ 58.4V (Battery Power)</li><li>Max. Current: 10A</li><li><em>Can Communication is Connected to the Robot PC</em></li></ul></div></div><p><br><br></p><h3 id="_12v-lan" tabindex="-1">12V-LAN <a class="header-anchor" href="#_12v-lan" aria-label="Permalink to &quot;12V-LAN&quot;">​</a></h3><div class="pin-map-row"><figure style="margin:0;"><img src="'+p+'" alt="User port 12V-LAN pin map"></figure><div><table><tr><th>Pin</th><th>Function</th><th>Color</th></tr><tr><td>1</td><td>VCC</td><td>Red</td></tr><tr><td>2</td><td>GND</td><td>Black</td></tr><tr><td>3</td><td>LAN TX+</td><td>White/Green</td></tr><tr><td>4</td><td>LAN TX-</td><td>Green</td></tr><tr><td>5</td><td>LAN RX+</td><td>White/Orange</td></tr><tr><td>6</td><td>LAN RX-</td><td>Orange</td></tr></table><ul><li>VCC: 12V</li><li>Max. Current: 2A</li><li>Network Switch Speeds: Fast Ethernet (100Mbps)</li><li><em>Lan Communication is Connected to the switching hub</em></li></ul></div></div><p><br><br></p><h3 id="lidar" tabindex="-1">LiDAR <a class="header-anchor" href="#lidar" aria-label="Permalink to &quot;LiDAR&quot;">​</a></h3><p>Present on <strong><a href="#panel-v1">panel version 1</a></strong> only. On <a href="#panel-v2">version 2</a>, LiDAR connects through a <code>12V/LAN</code> port.</p><div class="pin-map-row"><figure style="margin:0;"><img src="'+g+'" alt="User port LiDAR pin map"></figure><div><table><tr><th>Pin</th><th>Function</th><th>Color</th></tr><tr><td>1</td><td>VCC</td><td>Red</td></tr><tr><td>2</td><td>GND</td><td>Black</td></tr><tr><td>3</td><td>LAN TX+</td><td>White/Green</td></tr><tr><td>4</td><td>LAN TX-</td><td>Green</td></tr><tr><td>5</td><td>LAN RX+</td><td>White/Orange</td></tr><tr><td>6</td><td>LAN RX-</td><td>Orange</td></tr></table><ul><li>VCC: 12V</li><li>Max. Current: 2A</li><li>Network Switch Speeds: Fast Ethernet (100Mbps)</li><li><em>Lan Communication is Connected to the User PC</em></li></ul></div></div><h2 id="direct-pc-port" tabindex="-1">Direct PC Port <a class="header-anchor" href="#direct-pc-port" aria-label="Permalink to &quot;Direct PC Port&quot;">​</a></h2><p>Two USB-C ports connect straight to the onboard PCs. They are the same two ports on both versions; only the labels changed.</p><div class="rbq-compare"><figure><img src="'+f+'" alt="Direct PC ports, version 1"><figcaption>Version 1</figcaption></figure><figure><img src="'+u+'" alt="Direct PC ports, version 2"><figcaption>Version 2</figcaption></figure></div><table tabindex="0"><thead><tr><th style="text-align:left;">Connects to</th><th style="text-align:left;">Version 1</th><th style="text-align:left;">Version 2</th></tr></thead><tbody><tr><td style="text-align:left;">User PC</td><td style="text-align:left;"><code>VISION</code></td><td style="text-align:left;"><code>U-PC</code></td></tr><tr><td style="text-align:left;">Robot PC</td><td style="text-align:left;"><code>MOTION</code></td><td style="text-align:left;"><code>R-PC</code></td></tr></tbody></table>',36)])])}const q=m(P,[["render",v]]);export{L as __pageData,q as default};
